export const SUBJECT_ROOMS={'국어':['classroom','library'],'수학':['classroom','computer'],'사회':['classroom','computer','audiovisual'],'도덕':['classroom','audiovisual'],'과학':['classroom','science','computer'],'체육':['classroom','playground','gym'],'음악':['classroom','music'],'미술':['classroom','art'],'영어':['classroom','computer','audiovisual'],'실과':['classroom','computer','art'],'바른 생활':['classroom'],'슬기로운 생활':['classroom','science'],'즐거운 생활':['classroom','music','art'],'창체':['classroom','library','computer','audiovisual']};
export const subjectRooms=subject=>SUBJECT_ROOMS[subject]||['classroom'];
export function methods(subject,digital=false){const d=DATA[subject]||DATA['창체'];return d[0].map((name,i)=>({id:'m'+i,name,desc:[`관찰·시범을 통해 ${d[1][0][0]}에 접근해요.`,`짝이나 모둠의 서로 다른 생각을 비교해요.`,`방법을 바꾸어 표현하고 서로 질문해요.`,`스스로 선택하고 근거를 정리해요.`][i],icon:['search','users-round','lightbulb','notebook-pen'][i]})).concat(digital?[{id:'digital',name:'디지털 자료 탐구',desc:'화면 자료와 자신의 기록을 비교하며 근거를 확인해요.',icon:'tablet'}]:[]);}
export function design(subject,progress=0,method='m0',grade=3){const d=DATA[subject]||DATA['창체'],index=progress%3,v=d[1][index],m=methods(subject,true).find(m=>m.id===method)||methods(subject)[0];const question=grade<=2?v[2]+' 선생님이 처음 한 번만 같이 해 주세요.':grade>=5?v[2]+' 우리 방법도 먼저 설명해 보고 싶어요.':v[2];return {id:subject+'-'+index+'-'+method,title:v[0],goal:v[1],scene:question,method:m.name,steps:['시작 · 경험과 예상 나누기','활동 · '+m.name,'정리 · '+v[3]],choices:[[v[3],`직접 해 본 흔적을 보며 ${v[1]}를 확인합니다.`,4,2],['짝의 방법과 나란히 비교하기',`${v[0]}에서 서로 다른 선택의 까닭을 듣습니다.`,3,4],['작은 단계로 나누어 다시 시도하기',`${v[3]}부터 시범을 보고 각자 다시 해 봅니다.`,2,4]],reply:`“${v[3].replace(/기$/,'니')} 제 생각을 더 설명할 수 있겠어요.” 학생이 활동 기록에 새 표시를 남깁니다.`,evidence:`${v[1]}: 학생이 실제로 보인 말·그림·방법을 한 줄로 남겨요.`};}
export function classroomSituation(state,method){if(state.order<45)return '여러 목소리가 겹쳐 안내가 잘 들리지 않습니다. 잠시 멈춰 신호와 활동 순서를 확인합니다.';if(state.unity<50&&['m1','m2'].includes(method))return '모둠에서 역할을 맡는 속도가 다릅니다. 설명·도구·기록·발표 역할을 나누어 참여를 살펴봅니다.';if(method==='digital')return '기기 사용 속도가 달라 먼저 끝낸 학생은 친구에게 답 대신 조작 방법을 설명합니다.';if(method==='m3')return '조용히 생각하는 학생과 먼저 제안하는 학생이 함께 있습니다. 각자의 기록을 확인하며 의견을 모읍니다.';return '학생들이 선택한 방법을 시험하고 있습니다. 조용함과 시끄러움만으로 참여를 판단하지 않고 실제 활동을 살펴봅니다.';}
